#ifndef SCAMP_FIB_H
#define SCAMP_FIB_H

#include "core.h"
#include <unordered_map>
#include <vector>

struct RouteEntry {
    ip6_t addr;
    int len;
    nexthop_t hop;
};

// Live FIB: last-write-wins puts of normalized prefixes and longest prefix
// matching queries.  Every distinct normalized prefix is kept, even when it is
// redundant or shares its hop with another prefix.
class LiveFib {
public:
    void put(ip6_t addr, int len, nexthop_t hop);
    nexthop_t query(ip6_t addr) const;
    std::vector<RouteEntry> routes() const;

private:
    struct Key {
        uint64_t hi;
        uint64_t lo;
        int len;
        bool operator==(const Key& o) const {
            return len == o.len && hi == o.hi && lo == o.lo;
        }
    };
    struct KeyHash {
        size_t operator()(const Key& k) const {
            uint64_t h = k.hi * 0x9e3779b97f4a7c15ULL;
            h ^= k.lo + 0x9e3779b97f4a7c15ULL + (h << 6) + (h >> 2);
            h ^= (uint64_t)k.len * 0xc2b2ae3d27d4eb4fULL + (h << 6) + (h >> 2);
            return (size_t)h;
        }
    };
    std::unordered_map<Key, nexthop_t, KeyHash> map_;
};

#endif
EOF
cat > /workspace/src/fib.cpp << 'EOF'
#include "fib.h"

void LiveFib::put(ip6_t addr, int len, nexthop_t hop) {
    ip6_t m = mask_address(addr, len);
    Key k;
    k.hi = m.hi;
    k.lo = m.lo;
    k.len = len;
    map_[k] = hop;
}

nexthop_t LiveFib::query(ip6_t addr) const {
    for (int len = 128; len >= 0; --len) {
        ip6_t m = mask_address(addr, len);
        Key k;
        k.hi = m.hi;
        k.lo = m.lo;
        k.len = len;
        std::unordered_map<Key, nexthop_t, KeyHash>::const_iterator it = map_.find(k);
        if (it != map_.end()) return it->second;
    }
    return LPM_INVALID_NH;
}

std::vector<RouteEntry> LiveFib::routes() const {
    std::vector<RouteEntry> out;
    out.reserve(map_.size());
    for (std::unordered_map<Key, nexthop_t, KeyHash>::const_iterator it = map_.begin();
         it != map_.end(); ++it) {
        RouteEntry e;
        e.addr.hi = it->first.hi;
        e.addr.lo = it->first.lo;
        e.len = it->first.len;
        e.hop = it->second;
        out.push_back(e);
    }
    return out;
}
